{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.33) and model overestimates.",
    "Reduce forecast bias when recent history shows strong upward momentum (e.g., 3-5 consecutive spikes) to avoid overshoot.",
    "Apply mean reversion correction if model consistently overpredicts prices after a sharp spike (e.g., >10% above true outcome for 3+ days).",
    "Increase forecast conservatism when sentiment is positive (sentiment > 0.5) and historical volatility is low — avoid overreacting to sentiment.",
    "Correct for lagged behavior: if true outcome is significantly lower than model forecast for 2+ consecutive days, reduce forecast by 5-10% to account for delayed market reaction.",
    "When sentiment is positive but true outcome is below forecast, reduce forecast by 5-15% to avoid overconfidence in sentiment-driven spikes."
  ]
}
